style.css:
body {
  margin: 0;
  min-height: 100vh;

  /* dark anime background */
  background-color: #000;
  background-image:
    radial-gradient(circle at 70% 40%, rgba(255, 60, 60, 0.15), transparent 40%),
    radial-gradient(circle at 80% 60%, rgba(140, 0, 255, 0.12), transparent 45%);

  background-repeat: no-repeat;
  background-size: cover;

  color: #ffffff;
  font-family: Arial, sans-serif;
}
